/* Team-controlled tactical rooms. Character sheets are imported as battle copies. */
let tacticalClient=null,tacticalState=null,tacticalRoom=null,tacticalCode='',tacticalMembers=[],tacticalUid=null,tacticalDemo=false,tacticalSelected='',tacticalMode='walk',tacticalAttack=0,tacticalBrush='',tacticalPending=false,tacticalStatus='',tacticalDialog=null,tacticalUnitDraft=null,tacticalZoom=42,tacticalAutoUid=null;
const tacticalInvitation=new URLSearchParams(location.search).get('battle')||'';
playPages.splice(2,0,['Тактика',9]);
function tacticalSelf(){return tacticalDemo?'demo':cloudUser?.uid;}
function tacticalOwner(){return tacticalDemo||tacticalRoom?.ownerUid===cloudUser?.uid;}
function tacticalCanControl(unit){return tacticalState&&TacticalBattle.owns(tacticalState,tacticalSelf(),unit,tacticalRoom?.ownerUid||'demo');}
function tacticalTeam(){return tacticalState?.teams.find(t=>t.ownerUid===tacticalSelf());}
function tacticalPlayerName(){return cloudUser?.displayName||cloudUser?.email?.split('@')[0]||'Игрок';}
function tacticalNumber(value,fallback){const n=Number.parseFloat(value);return Number.isFinite(n)?n:fallback;}
function tacticalSnapshot(record){
 const previous=state;
 try{
  prepareCharacter(record.data);migrateEffects();refreshEffectAp();syncMaxHp();const movement=movementValues();
  const attacks=state.items.filter(i=>i.category==='Оружие'&&i.equipped).slice(0,8).map(item=>{const a=attackNumbers(item),ammo=attackAmmo(item);return {name:item.name,cost:Math.max(1,a.cost||6),chance:a.chance??50,damage:a.damage,bb:a.bb??0,range:Math.max(1,tacticalNumber(a.range,1)),ammo:ammo.cost?ammo.current:null,ammoCost:ammo.cost};});
  return TacticalBattle.sanitizeUnit({name:state.info.name,sourceId:record.id,hpMax:state.info.maxhp,hp:state.info.hp,apMax:Math.max(1,state.play.apMax),walk:movement.walk||1,run:movement.run||2,jump:movement.jump||0,jumpCost:movement.jumpCost||2,reaction:statTotal('RTC'),armor:state.zones[1].armor||0,attacks});
 }finally{state=previous;applyUiScales();}
}
function tacticalDefaultUnit(){return {name:'Новый боец',hpMax:100,hp:100,apMax:10,walk:1,run:2,jump:4,jumpCost:2,reaction:10,armor:0,attacks:[{name:'Атака',cost:6,chance:50,damage:'1d100',bb:0,range:6,ammo:12,ammoCost:1}]};}
function tacticalReport(message,error=false){tacticalStatus=message;document.querySelectorAll('[data-tactical-status]').forEach(el=>{el.textContent=message;el.classList.toggle('cloud-error',error);});}
function tacticalRefresh(){
 if(page!==9||libraryHome)return;if(document.querySelector('dialog[open]'))return;
 const board=document.querySelector('.tactical-map-scroll'),scroll=board?{x:board.scrollLeft,y:board.scrollTop}:null;render();const next=document.querySelector('.tactical-map-scroll');if(next&&scroll){next.scrollLeft=scroll.x;next.scrollTop=scroll.y;}
}
function tacticalDisconnect(){tacticalClient?.disconnect();tacticalClient=null;tacticalState=null;tacticalRoom=null;tacticalCode='';tacticalMembers=[];tacticalSelected='';tacticalPending=false;tacticalDemo=false;tacticalBrush='';}
function tacticalRoomClient(){
 if(!cloudUser||!cloudApi?.fs||cloudSwitching)throw Error('Войдите через Google, чтобы играть онлайн.');
 const uid=cloudUser.uid;return new BattleRoomClient({fs:cloudApi.fs,db:cloudDb,uid,displayName:tacticalPlayerName(),
  onState:(battle,room,code)=>{if(cloudUser?.uid!==uid)return;tacticalState=battle;tacticalRoom=room;tacticalCode=code;tacticalDemo=false;if(!battle.units.some(u=>u.id===tacticalSelected))tacticalSelected=battle.units.find(u=>tacticalCanControl(u))?.id||battle.units[0]?.id||'';try{localStorage.setItem('tactical-room:'+uid,code);}catch{}tacticalRefresh();},
  onMembers:members=>{if(cloudUser?.uid===uid){tacticalMembers=members;tacticalRefresh();}},
  onStatus:(text,error)=>{if(cloudUser?.uid===uid)tacticalReport(text,error);},
  onResult:(status,message)=>{if(cloudUser?.uid!==uid)return;tacticalPending=false;tacticalReport(status==='rejected'?message:'Действие подтверждено',status==='rejected');if(status==='rejected')toast(message);tacticalRefresh();}
 });
}
async function tacticalConnect(create=false){
 const code=document.querySelector('#tactical-code')?.value||tacticalInvitation,team=document.querySelector('#tactical-team-name')?.value||'Команда '+tacticalPlayerName(),map=document.querySelector('#tactical-new-map')?.value||'ruins';
 tacticalDisconnect();const client=tacticalRoomClient();tacticalClient=client;tacticalPending=true;tacticalReport('Подключаем комнату…');
 try{tacticalCode=create?await client.create(team,map):await client.join(code,team);tacticalDialog=null;tacticalReport('Подключено');}
 catch(error){tacticalReport(client.message(error),true);client.disconnect();tacticalClient=null;throw error;}
 finally{tacticalPending=false;tacticalRefresh();}
}
async function tacticalSend(kind,payload={}){
 if(tacticalPending)throw Error('Дождитесь подтверждения предыдущего действия.');
 if(tacticalDemo){tacticalState=TacticalBattle.apply(tacticalState,{kind,payload},'demo','demo',()=>crypto.getRandomValues(new Uint32Array(1))[0]/4294967296);tacticalDialog=null;tacticalRefresh();return;}
 if(!tacticalClient)throw Error('Сначала подключитесь к комнате.');tacticalPending=true;tacticalReport('Ожидаем подтверждения ведущего…');tacticalRefresh();
 try{await tacticalClient.submit(kind,payload);}catch(error){tacticalPending=false;tacticalReport(tacticalClient.message(error),true);tacticalRefresh();throw error;}
}
function tacticalDemoBattle(){
 tacticalDisconnect();tacticalDemo=true;tacticalRoom={ownerUid:'demo'};let b=TacticalBattle.create('demo','Разведчики','ruins');b=TacticalBattle.apply(b,{kind:'team',payload:{name:'Рейдеры'}},'demo','demo');b=TacticalBattle.apply(b,{kind:'team',payload:{name:'Охрана'}},'demo','demo');
 for(const [ti,team] of b.teams.entries())for(let n=0;n<2;n++){const unit=tacticalDefaultUnit();unit.name=['Разведчик','Рейдер','Страж'][ti]+' '+(n+1);unit.reaction=15-ti*3;unit.hp=unit.hpMax=160;unit.attacks[0]={...unit.attacks[0],name:'Карабин',cost:4,chance:70,damage:'2d20 + 10',range:12};b=TacticalBattle.apply(b,{kind:'addUnit',payload:{teamId:team.id,unit}},'demo','demo');}
 tacticalState=b;tacticalSelected=b.units[0].id;tacticalStatus='Демо: ведущий управляет всеми командами.';tacticalRefresh();
}
function tacticalLocationOptions(selected='ruins'){return Object.entries(TacticalBattle.locations).map(([key,m])=>`<option value="${key}" ${key===selected?'selected':''}>${m.name}</option>`).join('');}
function renderTacticalEntry(){let last='';try{last=cloudUser?localStorage.getItem('tactical-room:'+cloudUser.uid)||'':'';}catch{}return `<section class="battle-card tactical-entry"><div class="tag">SACRALIC / ONLINE TACTICS</div><h1>У каждой команды — свой игрок</h1><p>Создайте комнату, выберите локацию и пригласите друзей по коду.</p><div class="tactical-entry-grid"><div><h2>Создать сражение</h2><label>Ваша команда<input id="tactical-team-name" maxlength="50" value="Команда ${esc(tacticalPlayerName())}"></label><label>Локация<select id="tactical-new-map">${tacticalLocationOptions()}</select></label><button class="primary-action" data-tactical="create" ${!cloudUser||tacticalPending?'disabled':''}>Создать комнату</button></div><div><h2>Присоединиться</h2><label>Код комнаты<input id="tactical-code" maxlength="12" autocomplete="off" autocapitalize="characters" placeholder="ABCD2345" value="${esc(tacticalInvitation||last)}"></label><button data-tactical="join" ${!cloudUser||tacticalPending?'disabled':''}>Войти в комнату</button><button data-tactical="demo">Посмотреть демо</button>${!cloudUser?'<button data-cloud="login">Войти через Google</button>':''}</div></div><p data-tactical-status role="status">${esc(tacticalStatus)}</p><details><summary>Как устроен бой</summary>${tacticalHelp()}</details></section>`;}
function tacticalHelp(){return '<div class="tactical-help"><p>До 8 команд, по 8 бойцов. Каждый игрок управляет своей командой; ведущий выбирает карту, добавляет команды NPC и запускает бой. Ведущий должен держать комнату открытой: он подтверждает действия игроков.</p><p>Команды ходят по очереди, порядок определяется максимальной реакцией в команде. ОД каждого бойца восстанавливаются в начале нового раунда. На карте одна клетка равна одному метру. Движение — по восьми направлениям без прохода через углы стен. Трудная местность считается за две клетки.</p><p>Атака проверяет дальность, прямую видимость и d100 против шанса. Укрытие снижает шанс на 20 п.п. Поглощение брони = (AR − AB) × 10%, от 0 до 100%. Расход ОД и патронов применяется даже при промахе; боезапас может стать отрицательным. Криты, ответная защита, поля и травмы остаются на решении ведущего; HP можно поправить вручную.</p><p>Бойцы в комнате — копии листов. Боевые HP и боезапас не перезаписывают исходных персонажей. Код комнаты служит приглашением; не публикуйте его, если не хотите новых участников.</p></div>';}
function renderTacticalMap(){
 const b=tacticalState,unit=b.units.find(u=>u.id===tacticalSelected),canMove=unit&&tacticalCanControl(unit)&&b.phase==='battle'&&TacticalBattle.activeTeam(b)?.id===unit.teamId;
 let reach=null;if(canMove&&tacticalMode!=='attack'&&tacticalMode!=='jump')reach=TacticalBattle.paths(b,unit).dist;
 return `<div class="tactical-map-scroll" tabindex="0" aria-label="Карта боя, можно прокручивать"><div class="tactical-map theme-${b.map.key}" style="--battle-cols:${b.map.w};--battle-cell:${tacticalZoom}px" role="group" aria-label="${esc(b.map.name)}">${Array.from({length:b.map.w*b.map.h},(_,i)=>{const x=i%b.map.w,y=Math.floor(i/b.map.w),terrain=b.map.tiles[i],token=b.units.find(u=>u.x===x&&u.y===y),team=token&&b.teams.find(t=>t.id===token.teamId);let cost=null;if(canMove&&!token&&terrain!=='#'&&tacticalMode!=='attack'){if(tacticalMode==='jump'){if(TacticalBattle.distance(unit,{x,y})<=unit.jump&&TacticalBattle.lineOfSight(b,unit,{x,y}))cost=unit.jumpCost;}else{const steps=reach?.get(i);if(steps!==undefined)cost=Math.max(1,Math.ceil(steps/unit[tacticalMode]));}}const reachable=cost!==null&&cost<=unit.ap;return `<button class="battle-cell terrain-${terrain==='#'?'wall':terrain==='~'?'rough':terrain==='c'?'cover':'floor'} ${token?.id===tacticalSelected?'selected':''} ${token?.hp===0?'down':''} ${reachable?'reachable':''}" data-tactical="cell" data-x="${x}" data-y="${y}" aria-label="Клетка ${x+1}:${y+1}${token?' · '+esc(token.name)+' · '+token.hp+' HP':terrain==='#'?' · стена':terrain==='~'?' · трудная местность':terrain==='c'?' · укрытие':''}${reachable?' · '+cost+' ОД':''}">${token?`<span class="battle-token" style="--team-color:${team.color}">${esc(token.name.split(/\s/).map(w=>w[0]).join('').slice(0,2))}</span><span class="battle-token-hp" style="--health:${Math.round(token.hp/token.hpMax*100)}%"></span>`:terrain==='#'?'<span aria-hidden="true">▰</span>':terrain==='c'?'<span aria-hidden="true">▱</span>':reachable?`<small>${cost}</small>`:''}</button>`;}).join('')}</div></div>`;
}
function renderTacticalUnit(){
 const b=tacticalState,u=b.units.find(v=>v.id===tacticalSelected);if(!u)return '<p class="muted">Выберите бойца на карте или в списке команды.</p>';
 const owned=tacticalCanControl(u),turn=b.phase==='battle'&&TacticalBattle.activeTeam(b)?.id===u.teamId&&owned&&u.hp>0,team=b.teams.find(t=>t.id===u.teamId);
 return `<div class="tactical-unit-head"><span class="tactical-team-dot" style="background:${team.color}"></span><h2>${esc(u.name)}</h2><small>${esc(team.name)}</small></div><div class="play-summary">${metric('HP',u.hp+' / '+u.hpMax)}${metric('ОД',u.ap+' / '+u.apMax)}${metric('Шаг / бег',u.walk+' / '+u.run)}${metric('Броня / реакция',u.armor+' / '+u.reaction)}</div>${b.phase==='lobby'&&owned?`<p class="muted">Нажмите свободную клетку, чтобы расставить бойца.</p><button data-tactical="remove-unit" data-unit="${u.id}">Убрать из команды</button>`:''}${turn?`<div class="tactical-modes">${[['walk','Шаг'],['run','Бег'],['jump','Прыжок']].map(([key,name])=>`<button data-tactical="mode" data-mode="${key}" aria-pressed="${tacticalMode===key}" ${tacticalPending?'disabled':''}>${name}</button>`).join('')}</div><div class="tactical-unit-actions"><button data-tactical="action" data-action="stand" ${u.ap<4||tacticalPending?'disabled':''}>Встать · 4 ОД</button><button data-tactical="action" data-action="prone" ${u.ap<1||tacticalPending?'disabled':''}>Лечь · 1 ОД</button></div>`:''}<div class="tactical-attacks">${u.attacks.map((a,i)=>`<button data-tactical="select-attack" data-attack="${i}" ${!turn||u.ap<a.cost||tacticalPending?'disabled':''} aria-pressed="${tacticalMode==='attack'&&tacticalAttack===i}"><b>${esc(a.name)}</b><strong>${a.chance}%</strong><span>${esc(a.damage)} · ${a.cost} ОД · ББ ${a.bb} · ${a.range} кл.</span>${a.ammo!==null?`<small>Боезапас ${a.ammo} · расход ${a.ammoCost}</small>`:''}</button>`).join('')||'<p class="muted">Нет настроенных атак.</p>'}</div>${tacticalOwner()?`<button data-tactical="hp" data-unit="${u.id}">Изменить HP</button>`:''}`;
}
function renderTacticalPage(){
 if(!tacticalState)return renderTacticalEntry();const b=tacticalState,active=TacticalBattle.activeTeam(b),hostOnline=tacticalDemo||Date.now()-(tacticalRoom?.hostSeenAt?.toMillis?.()||0)<45000;
 return `<section class="tactical-header"><div><div class="tag">${tacticalDemo?'ДЕМО / ЛОКАЛЬНО':'ОНЛАЙН / '+tacticalCode}</div><h1>${esc(b.map.name)}</h1><p>${b.phase==='lobby'?'Расстановка команд':b.phase==='paused'?'Пауза':b.phase==='finished'?'Бой завершён':'Раунд '+b.round+' · ход «'+esc(active?.name||'—')+'»'}</p></div><div class="tactical-toolbar">${!tacticalDemo?'<button data-tactical="invite">Скопировать приглашение</button>':''}<button data-tactical="help" aria-label="Правила тактического боя">i</button><button data-tactical="leave">Выйти из комнаты</button></div></section><p class="tactical-status ${!hostOnline?'cloud-error':''}" data-tactical-status role="status">${esc(!hostOnline?'Ведущий не в сети. Действия ждут его возвращения.':tacticalStatus||'Подключено')}</p><div class="tactical-team-strip">${b.teams.map(t=>`<div class="tactical-team-chip ${active?.id===t.id&&b.phase==='battle'?'active':''}" style="--team-color:${t.color}"><b>${esc(t.name)}</b><small>${t.ownerUid===tacticalSelf()?'Ваша команда · ':''}${b.units.filter(u=>u.teamId===t.id&&u.hp>0).length} / ${b.units.filter(u=>u.teamId===t.id).length} бойцов</small></div>`).join('')}</div><div class="tactical-layout"><section class="battle-card tactical-map-card"><div class="tactical-map-toolbar"><span>1 клетка · ${tacticalMode==='attack'?'выберите цель':tacticalBrush?'рисование карты':'выберите клетку'}</span><button data-tactical="zoom" data-delta="-6" aria-label="Уменьшить карту">−</button><button data-tactical="zoom" data-delta="6" aria-label="Увеличить карту">+</button></div>${renderTacticalMap()}<div class="tactical-legend"><span>▰ Стена</span><span>≈ Трудно · ×2</span><span>▱ Укрытие · −20%</span></div>${tacticalOwner()&&b.phase==='lobby'?`<details><summary>Локация и редактирование карты</summary><select id="tactical-location" aria-label="Локация боя">${tacticalLocationOptions(b.map.key)}</select><div class="tactical-modes">${[['','Расстановка'],['.','Пол'],['#','Стена'],['~','Трудно'],['c','Укрытие']].map(([value,label])=>`<button data-tactical="brush" data-brush="${value}" aria-pressed="${tacticalBrush===value}">${label}</button>`).join('')}</div></details>`:''}</section><aside class="battle-card tactical-inspector">${renderTacticalUnit()}${b.phase==='battle'&&(tacticalOwner()||active?.ownerUid===tacticalSelf())?`<button class="primary-action tactical-end-turn" data-tactical="end-turn" ${tacticalPending?'disabled':''}>Завершить ход команды →</button>`:''}</aside></div><div class="tactical-bottom"><section class="battle-card"><div class="section-heading"><h2>Составы команд</h2>${b.phase==='lobby'?'<button data-tactical="add-unit">+ Боец</button>':''}${tacticalOwner()&&b.phase==='lobby'?'<button data-tactical="add-team">+ NPC-команда</button>':''}</div>${b.teams.map(t=>`<div class="tactical-roster-team"><h3 style="color:${t.color}">${esc(t.name)}</h3>${b.units.filter(u=>u.teamId===t.id).map(u=>`<button data-tactical="unit" data-unit="${u.id}" aria-pressed="${u.id===tacticalSelected}"><span>${esc(u.name)}</span><small>${u.hp} HP · ${u.ap} ОД</small></button>`).join('')||'<small class="muted">Пока нет бойцов</small>'}</div>`).join('')}${!tacticalDemo?`<small class="muted">Подключено игроков: ${tacticalMembers.length}. Ведущий держит комнату открытой.</small>`:''}<div class="tactical-host-actions">${tacticalOwner()&&b.phase==='lobby'?'<button class="primary-action" data-tactical="start">Начать бой</button>':''}${tacticalOwner()&&['battle','paused'].includes(b.phase)?`<button data-tactical="pause">${b.phase==='paused'?'Продолжить':'Пауза'}</button>`:''}${tacticalOwner()&&b.history.length?'<button data-tactical="undo">↶ Отменить последнее действие</button>':''}</div></section><section class="battle-card tactical-log"><h2>Журнал сражения</h2>${b.log.map(message=>`<p>${esc(message)}</p>`).join('')||'<p class="muted">Пригласите игроков и расставьте команды.</p>'}</section></div>`;
}
function tacticalUnitFields(){const u=tacticalUnitDraft;return `<div class="fields">${[['name','Имя','text'],['hpMax','Макс. HP','number'],['hp','Текущие HP','number'],['apMax','ОД / раунд','number'],['reaction','Реакция','number'],['armor','Броня AR','number'],['walk','Шаг, клеток / ОД','number'],['run','Бег, клеток / ОД','number'],['jump','Прыжок, клеток','number'],['jumpCost','Прыжок, ОД','number']].map(([key,label,type])=>`<label>${label}<input data-battle-unit="${key}" type="${type}" value="${esc(u[key])}" ${type==='number'?'min="0" step="any"':'maxlength="80"'}></label>`).join('')}</div><div class="section-heading"><h3>Атаки</h3><button data-tactical="draft-attack">+ Атака</button></div><div class="tactical-attack-editors">${u.attacks.map((a,i)=>`<details data-attack-row="${i}" open><summary>${esc(a.name)}</summary><div class="fields">${[['name','Название','text'],['damage','Урон, например 1d100 + 20','text'],['cost','Стоимость ОД','number'],['chance','Шанс, %','number'],['bb','ББ','number'],['range','Дальность, клеток','number'],['ammo','Боезапас (пусто — без боезапаса)','number'],['ammoCost','Расход за атаку','number']].map(([key,label,type])=>`<label>${label}<input data-battle-attack="${key}" type="${type}" value="${esc(a[key]??'')}" ${type==='number'?'step="any"':'maxlength="120"'}></label>`).join('')}</div><button data-tactical="draft-remove-attack" data-index="${i}">Убрать атаку</button></details>`).join('')}</div>`;}
function tacticalReadDraft(){const dialog=document.querySelector('#tactical-dialog');for(const input of dialog.querySelectorAll('[data-battle-unit]'))tacticalUnitDraft[input.dataset.battleUnit]=input.type==='number'?Number(input.value):input.value;tacticalUnitDraft.attacks=[...dialog.querySelectorAll('[data-attack-row]')].map(row=>Object.fromEntries([...row.querySelectorAll('[data-battle-attack]')].map(input=>[input.dataset.battleAttack,input.dataset.battleAttack==='ammo'&&input.value===''?null:input.type==='number'?Number(input.value):input.value])));}
function renderTacticalDialog(){if(!tacticalDialog)return '';let title='',body='',action='';const d=tacticalDialog;
 if(d.kind==='unit'){title='Добавить бойца';body=`<label>Команда<select id="tactical-unit-team">${tacticalState.teams.filter(t=>tacticalOwner()||t.ownerUid===tacticalSelf()).map(t=>`<option value="${t.id}" ${t.id===d.teamId?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label><label>Из своей библиотеки<select id="tactical-unit-source"><option value="">Собственный боец / NPC</option>${characterRecords.filter(r=>!r.deletedAt).map(r=>`<option value="${r.id}" ${tacticalUnitDraft.sourceId===r.id?'selected':''}>${esc(r.data.info.name)}</option>`).join('')}</select></label><div id="tactical-unit-fields">${tacticalUnitFields()}</div>`;action='save-unit';}
 if(d.kind==='team'){title='NPC-команда';body='<label>Название<input id="tactical-npc-team" maxlength="50" value="Противники"></label>';action='save-team';}
 if(d.kind==='hp'){const u=tacticalState.units.find(u=>u.id===d.unitId);title='HP · '+u.name;body=`<label>Текущие HP<input id="tactical-hp" type="number" min="0" max="${u.hpMax}" value="${u.hp}"></label>`;action='save-hp';}
 if(d.kind==='move'){title='Перемещение';body=`<p>${esc(d.unitName)} → ${d.x+1}:${d.y+1}</p><p>Стоимость: <b>${d.cost} ОД</b>.</p>`;action='confirm-move';}
 if(d.kind==='attack'){title='Подтвердить атаку';body=`<p>${esc(d.unitName)} → ${esc(d.targetName)}</p><p>${esc(d.attack.name)} · ${d.attack.cost} ОД · ${d.attack.chance}% до укрытия</p><p>${esc(d.attack.damage)} · ББ ${d.attack.bb}</p>`;action='confirm-attack';}
 if(d.kind==='help'){title='Правила тактического боя';body=tacticalHelp();}
 return `<dialog id="tactical-dialog" class="formula-dialog" aria-labelledby="tactical-dialog-title"><div class="toolbar"><h2 id="tactical-dialog-title">${esc(title)}</h2><button data-tactical="close-dialog" aria-label="Закрыть окно боя">×</button></div>${body}<p id="tactical-dialog-error" class="formula-error" role="status"></p>${action?`<div class="dialog-actions"><button data-tactical="close-dialog">Отмена</button><button data-tactical="${action}">Подтвердить</button></div>`:''}</dialog>`;
}
function tacticalOpenDialog(d){tacticalDialog=d;document.querySelector('#tactical-dialog')?.remove();document.querySelector('#view').insertAdjacentHTML('beforeend',renderTacticalDialog());document.querySelector('#tactical-dialog').showModal();}
function tacticalCloseDialog(){tacticalDialog=null;document.querySelector('#tactical-dialog')?.remove();}
const beforeTacticalRender=render;
render=function(){
 if(tacticalUid!==cloudUser?.uid){tacticalDisconnect();tacticalUid=cloudUser?.uid;tacticalDialog=null;tacticalAutoUid=null;}
 beforeTacticalRender();document.body.classList.toggle('tactical-page',page===9&&!libraryHome);
 if(libraryHome){document.querySelector('.library-heading .play-shortcuts')?.insertAdjacentHTML('beforeend','<button data-tactical="open">Тактический бой</button>');if(tacticalInvitation)document.querySelector('.library-heading')?.insertAdjacentHTML('afterend',`<section class="cloud-panel"><div><b>Приглашение в бой · ${esc(tacticalInvitation)}</b><p>Войдите через Google, чтобы управлять своей командой.</p></div><button data-tactical="open">Открыть бой</button></section>`);}
 if(page===9&&!libraryHome){if(tacticalDialog){document.querySelector('#view').insertAdjacentHTML('beforeend',renderTacticalDialog());document.querySelector('#tactical-dialog').showModal();}}
 if(cloudUser&&tacticalInvitation&&tacticalAutoUid!==cloudUser.uid){const invitationUid=cloudUser.uid;tacticalAutoUid=invitationUid;setTimeout(()=>{if(cloudUser?.uid!==invitationUid||tacticalAutoUid!==invitationUid)return;libraryHome=false;page=9;render();tacticalConnect(false).catch(error=>toast(error.message));},0);}
};
document.addEventListener('cancel',event=>{if(event.target.id==='tactical-dialog')tacticalCloseDialog();},true);
document.addEventListener('change',event=>{
 if(event.target.id==='tactical-location'){event.stopImmediatePropagation();tacticalSend('location',{key:event.target.value}).catch(error=>toast(error.message));}
 if(event.target.id==='tactical-unit-source'){event.stopImmediatePropagation();try{const record=characterRecords.find(r=>r.id===event.target.value);tacticalUnitDraft=record?tacticalSnapshot(record):tacticalDefaultUnit();document.querySelector('#tactical-unit-fields').innerHTML=tacticalUnitFields();}catch(error){document.querySelector('#tactical-dialog-error').textContent=error.message;}}
},true);
document.addEventListener('click',async event=>{
 const nav=event.target.closest('[data-page]');if(nav&&page===9&&!activeCharacterId&&+nav.dataset.page!==9){event.stopImmediatePropagation();libraryHome=true;page=0;render();return;}
 const button=event.target.closest('[data-tactical]');if(!button)return;event.stopImmediatePropagation();const d=button.dataset,u=tacticalState?.units.find(u=>u.id===tacticalSelected);
 try{switch(d.tactical){
  case 'open':libraryHome=false;page=9;render();return;
  case 'create':await tacticalConnect(true);return;
  case 'join':await tacticalConnect(false);return;
  case 'demo':tacticalDemoBattle();return;
  case 'leave':tacticalDisconnect();tacticalStatus='';tacticalRefresh();return;
  case 'invite':{const url=new URL(location.href);url.search='';url.searchParams.set('battle',tacticalCode);await navigator.clipboard.writeText(url.href);toast('Приглашение скопировано · '+tacticalCode);return;}
  case 'help':tacticalOpenDialog({kind:'help'});return;
  case 'close-dialog':tacticalCloseDialog();tacticalRefresh();return;
  case 'zoom':tacticalZoom=Math.max(26,Math.min(66,tacticalZoom+ +d.delta));tacticalRefresh();return;
  case 'unit':tacticalSelected=d.unit;tacticalMode='walk';tacticalRefresh();return;
  case 'mode':tacticalMode=d.mode;tacticalBrush='';tacticalRefresh();return;
  case 'brush':tacticalBrush=d.brush;tacticalRefresh();return;
  case 'cell':{
   const x=+d.x,y=+d.y,target=tacticalState.units.find(u=>u.x===x&&u.y===y);
   if(tacticalBrush){await tacticalSend('terrain',{x,y,tile:tacticalBrush});return;}
   if(tacticalMode==='attack'&&u&&target&&target.teamId!==u.teamId){if(TacticalBattle.distance(u,target)>u.attacks[tacticalAttack].range)throw Error('Цель вне дальности.');if(!TacticalBattle.lineOfSight(tacticalState,u,target))throw Error('Линия огня перекрыта.');tacticalOpenDialog({kind:'attack',unitName:u.name,targetName:target.name,unitId:u.id,targetId:target.id,attackIndex:tacticalAttack,attack:u.attacks[tacticalAttack]});return;}
   if(target){tacticalSelected=target.id;tacticalMode='walk';tacticalRefresh();return;}
   if(!u||!tacticalCanControl(u))throw Error('Выберите бойца своей команды.');
   if(tacticalState.phase==='lobby'){await tacticalSend('deploy',{unitId:u.id,x,y});return;}
   const move=TacticalBattle.movement(tacticalState,u,x,y,tacticalMode);if(move.cost>u.ap)throw Error('Недостаточно ОД.');tacticalOpenDialog({kind:'move',unitId:u.id,unitName:u.name,x,y,cost:move.cost,mode:tacticalMode});return;
  }
  case 'confirm-move':{const p=tacticalDialog;tacticalCloseDialog();await tacticalSend('move',{unitId:p.unitId,x:p.x,y:p.y,mode:p.mode});return;}
  case 'select-attack':tacticalAttack=+d.attack;tacticalMode='attack';tacticalBrush='';tacticalRefresh();return;
  case 'confirm-attack':{const p=tacticalDialog;tacticalCloseDialog();await tacticalSend('attack',{unitId:p.unitId,targetId:p.targetId,attackIndex:p.attackIndex});return;}
  case 'action':await tacticalSend('action',{unitId:u.id,action:d.action});return;
  case 'end-turn':await tacticalSend('endTurn');return;
  case 'start':await tacticalSend('start');return;
  case 'pause':await tacticalSend('pause');return;
  case 'undo':await tacticalSend('undo');return;
  case 'remove-unit':await tacticalSend('removeUnit',{unitId:d.unit});return;
  case 'add-team':tacticalOpenDialog({kind:'team'});return;
  case 'save-team':{const name=document.querySelector('#tactical-npc-team').value;tacticalCloseDialog();await tacticalSend('team',{name});return;}
  case 'hp':tacticalOpenDialog({kind:'hp',unitId:d.unit});return;
  case 'save-hp':{const id=tacticalDialog.unitId,value=Number(document.querySelector('#tactical-hp').value);tacticalCloseDialog();await tacticalSend('hp',{unitId:id,value});return;}
  case 'add-unit':{const team=tacticalTeam()||(tacticalOwner()?tacticalState.teams[0]:null);if(!team)throw Error('Дождитесь, пока ведущий добавит вашу команду.');const record=characterRecords.find(r=>r.id===activeCharacterId)||characterRecords.find(r=>!r.deletedAt);tacticalUnitDraft=record?tacticalSnapshot(record):tacticalDefaultUnit();tacticalOpenDialog({kind:'unit',teamId:team.id});return;}
  case 'draft-attack':tacticalReadDraft();if(tacticalUnitDraft.attacks.length>=8)throw Error('Максимум 8 атак.');tacticalUnitDraft.attacks.push({...tacticalDefaultUnit().attacks[0]});document.querySelector('#tactical-unit-fields').innerHTML=tacticalUnitFields();return;
  case 'draft-remove-attack':tacticalReadDraft();tacticalUnitDraft.attacks.splice(+d.index,1);document.querySelector('#tactical-unit-fields').innerHTML=tacticalUnitFields();return;
  case 'save-unit':{tacticalReadDraft();const unit=TacticalBattle.sanitizeUnit(tacticalUnitDraft);for(const a of unit.attacks)TacticalBattle.dice(a.damage,()=>0);const teamId=document.querySelector('#tactical-unit-team').value;tacticalCloseDialog();await tacticalSend('addUnit',{teamId,unit});return;}
 }}catch(error){const field=document.querySelector('#tactical-dialog-error');if(field)field.textContent=error.message;else{tacticalReport(error.message,true);toast(error.message);}}
},true);
render();
